def archive_workshop(apps, schema_editor):
    alias = schema_editor.connection.alias
    Dataset = apps.get_model("overbae", "Dataset")
    Cell = apps.get_model("overbae", "Cell")
    history_model = apps.get_model("overbae", "DatasetHistory")

    def save(dataset_id, kind, reference, payload):
        history_model.objects.using(alias).create(
            dataset_id=dataset_id,
            kind=kind,
            reference=str(reference),
            payload=json.loads(json.dumps(payload, cls=DjangoJSONEncoder)),
        )

    for dataset in Dataset.objects.using(alias).iterator(chunk_size=100):
        conversation = {
            key: getattr(dataset, key)
            for key in ("chat", "agent_id", "agent_messages", "agent_turn_key")
        }
        if any(conversation.values()):
            save(dataset.pk, "conversation", "", conversation)
        if dataset.operation:
            save(dataset.pk, "operation", "", dataset.operation)
        # Old worker leases cannot be resumed by the new runtime.
        Dataset.objects.using(alias).filter(pk=dataset.pk).update(operation={})
        if dataset.state == "diagnosing" or (
            dataset.state == "running"
            and not apps.get_model("overbae", "DatasetPipelineRun")
            .objects.using(alias)
            .filter(dataset_id=dataset.pk, state__in=["queued", "running"])
            .exists()
        ):
            Dataset.objects.using(alias).filter(pk=dataset.pk).update(state="idle", error="")

    for model, kind, relation in (
        ("WorkshopRun", "run", "dataset_id"),
        ("WorkshopWorkItem", "work_item", "run__dataset_id"),
        ("WorkshopRecord", "record", "run__dataset_id"),
    ):
        Model = apps.get_model("overbae", model)
        fields = [field.attname for field in Model._meta.concrete_fields]
        for row in Model.objects.using(alias).values(*fields, relation).iterator(chunk_size=100):
            save(row[relation], kind, row["id"], row)
    for cell in (
        Cell.objects.using(alias).filter(state__in=["proposed", "queued", "running"]).iterator()
    ):
        save(
            cell.dataset_id,
            "cell",
            cell.pk,
            {"state": cell.state, "script": cell.script, "review": cell.review},
        )
        Cell.objects.using(alias).filter(pk=cell.pk).update(
            state="failed", error="No published output."
        )


